def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    try:
        if tz is None:
            import datetime
            return datetime.time.fromtimestamp(nanoseconds / 1e9)
        else:
            import datetime
            import pytz
            timezone = pytz.timezone(tz)
            timestamp = nanoseconds / 1e9
            return timezone.localize(datetime.datetime.utcfromtimestamp(timestamp)).time()
    except Exception as e:
        raise ValueError(f"Error hydrating time: {e}")

def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if not isinstance(value, timedelta):
        raise TypeError("Expected a timedelta, got {}".format(type(value).__name__))
    return {
        'days': value.days,
        'seconds': value.seconds,
        'microseconds': value.microseconds
    }

