def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    minimal_classes = []
    for cls in classes:
        if not any(issubclass(c, cls) for c in minimal_classes):
            minimal_classes = [c for c in minimal_classes if not issubclass(cls, c)]
            minimal_classes.append(cls)
    return minimal_classes

