def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 0:
        return {}

    diff = {}
    for key, value in d1.items():
        if key not in d2:
            diff[key] = value
        elif isinstance(value, dict) and isinstance(d2.get(key), dict):
            sub_diff = difference(value, d2[key], level - 1)
            if sub_diff:
                diff[key] = sub_diff
        elif value != d2.get(key):
            diff[key] = value

    return diff

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if 0 <= coord < len(self.data):
        self.data[coord] += weight

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    import sys

    key_regex = re.compile(r'^[a-zA-Z0-9_]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9_ ,./-]+$', re.UNICODE)

    errors = []

    for key, value in labels.items():
        if isinstance(key, (int, bool)):
            errors.append({str(key): 'expected string or bytes-like object'})
            continue

        if not isinstance(key, str):
            errors.append({str(key): 'expected string or bytes-like object'})
            continue

        if not key_regex.match(key):
            errors.append({key: f"Label key '{key}' does not match the regex '^[a-zA-Z0-9_]+$'"})

        if isinstance(value, list):
            for item in value:
                if isinstance(item, (int, bool)):
                    errors.append({str(item): 'expected string or bytes-like object'})
                    continue

                if not isinstance(item, str):
                    errors.append({str(item): 'expected string or bytes-like object'})
                    continue

                if not value_regex.match(item):
                    errors.append({item: f"Label value '{item}' does not match the regex '^[a-zA-Z0-9_ ,./-]+$'"})
        else:
            if isinstance(value, (int, bool)):
                errors.append({str(value): 'expected string or bytes-like object'})
                continue

            if not isinstance(value, str):
                errors.append({str(value): 'expected string or bytes-like object'})
                continue

            if not value_regex.match(value):
                errors.append({value: f"Label value '{value}' does not match the regex '^[a-zA-Z0-9_ ,./-]+$'"})

    if errors:
        class ValidationError(Exception):
            def __init__(self, messages):
                self.messages = messages
                super().__init__(f"Validation errors: {messages}")

        raise ValidationError(errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    if not isinstance(manifest_dict, dict):
        raise ValueError("manifest_dict must be a dictionary")

    observer_schema = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value, False)
        elif isinstance(value, list):
            observer_schema[key] = [generate_default_observer_schema_dict(item, False) if isinstance(item, dict) else None for item in value]
        else:
            if first_level and key in ["apiVersion", "kind", "metadata", "name", "namespace"]:
                observer_schema[key] = value
            else:
                observer_schema[key] = None

    return observer_schema

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present
    """
    if not isinstance(last_applied_manifest, list) or not isinstance(observer_schema, list) or not isinstance(response, list):
        raise ValueError("All arguments must be lists")

    for obs_item, resp_item in zip(observer_schema, response):
        if isinstance(obs_item, dict) and isinstance(resp_item, dict):
            # Assuming there's a corresponding function to handle dictionaries
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[observer_schema.index(obs_item)], obs_item, resp_item)
        elif isinstance(obs_item, list) and isinstance(resp_item, list):
            update_last_applied_manifest_list_from_resp(last_applied_manifest[observer_schema.index(obs_item)], obs_item, resp_item)
        else:
            if observer_schema.index(obs_item) >= len(last_applied_manifest):
                last_applied_manifest.append(resp_item)
            elif last_applied_manifest[observer_schema.index(obs_item)] is None:
                last_applied_manifest[observer_schema.index(obs_item)] = resp_item

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for field, schema in observer_schema.items():
        if 'path' in schema:
            path = schema['path']
            try:
                value = response
                for key in path:
                    value = value[key]
            except KeyError:
                if 'default' in schema:
                    value = schema['default']
                else:
                    raise KeyError(f"The observed field {'.'.join(path)} is not present in the Kubernetes response")
        else:
            value = None  # or handle accordingly if no path is provided

        current = last_applied_manifest
        path = schema.get('path', [])
        for key in path[:-1]:
            if key not in current:
                current[key] = {}
            current = current[key]

        final_key = path[-1] if path else field
        if final_key not in current:
            current[final_key] = value

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        if not hasattr(app, 'spec') or not hasattr(app.spec, 'manifest'):
            raise ValueError("Application object does not have a valid spec.manifest")

        for resource in app.spec.manifest:
            if resource not in app.spec.observer_schema:
                # Generate default observer schema for the resource
                default_schema = {
                    "resources": [
                        {
                            "kind": resource['kind'],
                            "apiVersion": resource['apiVersion'],
                            "namespace": resource.get('metadata', {}).get('namespace', ''),
                            "name": resource['metadata']['name']
                        }
                    ]
                }
                if not app.spec.observer_schema:
                    app.spec.observer_schema = {}
                app.spec.observer_schema[resource['metadata']['name']] = default_schema

    except Exception as e:
        raise RuntimeError(f"Failed to generate default observer schema: {e}")

