def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    try:
        # Extract all digests from manifest files
        digests_in_manifest = set()
        for manifest_file in manifest_files:
            if not isinstance(manifest_file, dict):
                raise ValueError("Each manifest file should be a dictionary.")
            digests_in_manifest.update(manifest_file.get('digests', {}).keys())

        # Check if all required digests are present in the manifest
        for digest in digests_used:
            if digest not in digests_in_manifest:
                raise ValueError(f"Digest {digest} is required but not present in the manifest.")

        # Check if all digests in the manifest are used
        for digest in digests_in_manifest:
            if digest not in digests_used:
                raise ValueError(f"Digest {digest} is present in the manifest but not used.")

    except Exception as e:
        raise RuntimeError("Error checking digests: " + str(e))

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    path_map = {}
    try:
        for logical_path, file_info in inventory.get_files_for_version(version).items():
            if logical_path not in path_map:
                path_map[logical_path] = set()
            path_map[logical_path].update(file_info.get('content_files', []))
    except (AttributeError, KeyError) as e:
        raise ValueError(f"Inventory or version data is invalid: {e}")
    return path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary.")

    if not isinstance(manifest_files, list):
        raise ValueError("Manifest files must be a list.")

    for file_hash, file_info in fixity.items():
        if not isinstance(file_info, dict) or 'filepath' not in file_info:
            raise ValueError("Each fixity entry must be a dictionary with a 'filepath' key.")

        filepath = file_info['filepath']
        if filepath not in manifest_files:
            raise ValueError(f"Filepath '{filepath}' in fixity block is not listed in the manifest.")

    return True

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    try:
        return [f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))]
    except FileNotFoundError:
        raise FileNotFoundError(f"The path {path} does not exist.")
    except PermissionError:
        raise PermissionError(f"Permission denied to access the path {path}.")
    except Exception as e:
        raise RuntimeError(f"An error occurred: {e}")

