def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    for xpath in pubdate_xpaths:
        try:
            match = node.xpath(xpath)
            if match:
                return match[0]
        except Exception as e:
            continue
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    try:
        indent_str = '  ' * indent
        result = indent_str + repr(self)
        if debug:
            result += ' ' + str(self.__dict__)
        result += '\n'
        for attr in dir(self):
            if not attr.startswith('__') and not callable(getattr(self, attr)):
                value = getattr(self, attr)
                if hasattr(value, 'pretty'):
                    result += value.pretty(indent + 1, debug)
                else:
                    result += '  ' * (indent + 1) + f"{attr}: {value}\n"
        return result
    except Exception as e:
        return f"Error pretty printing {self}: {e}"

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from copy import deepcopy

    def apply_absorption(expr):
        if isinstance(expr, tuple) and len(expr) == 3:
            op = expr[0]
            if op == '&':
                left, right = expr[1], expr[2]
                if isinstance(right, tuple) and right[0] == '|':
                    if right[1] == left:
                        return left
                    if right[2] == left:
                        return left
                if isinstance(left, tuple) and left[0] == '|':
                    if left[1] == right:
                        return right
                    if left[2] == right:
                        return right
            elif op == '|':
                left, right = expr[1], expr[2]
                if isinstance(right, tuple) and right[0] == '&':
                    if right[1] == left:
                        return left
                    if right[2] == left:
                        return left
                if isinstance(left, tuple) and left[0] == '&':
                    if left[1] == right:
                        return right
                    if left[2] == right:
                        return right
        return expr

    def apply_negative_absorption(expr):
        if isinstance(expr, tuple) and len(expr) == 3:
            op = expr[0]
            if op == '&':
                left, right = expr[1], expr[2]
                if isinstance(right, tuple) and right[0] == '|':
                    if isinstance(right[1], tuple) and right[1][0] == '~' and right[1][1] == left:
                        return ('&', left, right[2])
                    if isinstance(right[2], tuple) and right[2][0] == '~' and right[2][1] == left:
                        return ('&', left, right[1])
            elif op == '|':
                left, right = expr[1], expr[2]
                if isinstance(right, tuple) and right[0] == '&':
                    if isinstance(right[1], tuple) and right[1][0] == '~' and right[1][1] == left:
                        return ('|', left, right[2])
                    if isinstance(right[2], tuple) and right[2][0] == '~' and right[2][1] == left:
                        return ('|', left, right[1])
        return expr

    def simplify(expr):
        expr = apply_absorption(expr)
        expr = apply_negative_absorption(expr)
        return expr

    simplified_args = []
    for arg in args:
        simplified_arg = simplify(arg)
        if isinstance(simplified_arg, tuple):
            simplified_arg = (simplified_arg[0], simplify(simplified_arg[1]), simplify(simplified_arg[2]))
        simplified_args.append(simplified_arg)

    return simplified_args

def base_config(user, etcd_host="localhost", etcd_port=2379):
    """Creates a configuration with some simple parameters, which have a default value
    that can be set.

    Args:
        user (str): the name of the user for the static authentication
        etcd_host (str): the host for the database.
        etcd_port (int): the port for the database.

    Returns:
        dict: the created configuration.

    """
    if not isinstance(user, str):
        raise ValueError("User must be a string.")
    if not isinstance(etcd_host, str):
        raise ValueError("etcd_host must be a string.")
    if not isinstance(etcd_port, int):
        raise ValueError("etcd_port must be an integer.")
    if etcd_port <= 0:
        raise ValueError("etcd_port must be a positive integer.")

    return {
        "user": user,
        "etcd_host": etcd_host,
        "etcd_port": etcd_port
    }

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    try:
        import unicode
    except ImportError:
        # Python 3: unicode is not defined, return the result as is
        return namefunc()
    else:
        # Python 2: Convert unicode to bytestrings
        return tuple(name.encode('utf-8') if name is not None else None for name in namefunc())

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        import pkg_resources
        version = pkg_resources.get_distribution('your_package_name').version
    except (ImportError, pkg_resources.DistributionNotFound):
        version = "Unknown"
    return version

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not isinstance(pieces, list) or not all(isinstance(piece, str) for piece in pieces):
        raise ValueError("The 'pieces' argument must be a list of strings.")
    if not isinstance(style, str):
        raise ValueError("The 'style' argument must be a string.")

    if style == 'dotted':
        return '.'.join(pieces)
    elif style == 'dashed':
        return '-'.join(pieces)
    elif style == 'underscored':
        return '_'.join(pieces)
    else:
        raise ValueError(f"Unsupported style: {style}")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if '+' in pieces:
        return '.'
    else:
        return '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    if not commands:
        raise ValueError("No commands provided")

    if not env:
        env = os.environ

    command_list = [commands] + args

    try:
        if verbose:
            print('Running command:', ' '.join(command_list))

        with open(os.devnull, 'w') as devnull:
            stderr = devnull if hide_stderr else None
            result = subprocess.run(command_list, cwd=cwd, env=env, stderr=stderr, check=True)

        if verbose:
            print('Command executed successfully:', result.stdout.decode().strip())

        return result.stdout.decode()

    except subprocess.CalledProcessError as e:
        error_message = f"Command {' '.join(command_list)} failed with return code {e.returncode}"
        if verbose:
            print(error_message)
        raise RuntimeError(error_message) from e

    except FileNotFoundError as e:
        error_message = f"Command {' '.join(command_list)} not found"
        if verbose:
            print(error_message)
        raise FileNotFoundError(error_message) from e

    except Exception as e:
        error_message = f"An error occurred while running the command {' '.join(command_list)}"
        if verbose:
            print(error_message)
        raise Exception(error_message) from e

def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    def decorator(func):
        if not hasattr(func, 'vcs_handlers'):
            func.vcs_handlers = {}
        func.vcs_handlers[vcs] = method
        return func
    return decorator

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    try:
        for obj in self.iterate_objects():
            num_objects += 1
            is_valid = True
            if validate_objects and not obj.is_valid():
                is_valid = False
                if show_warnings:
                    print(f"Warning: Object {obj} is not valid.")
            if check_digests and not obj.check_digest():
                is_valid = False
                if show_warnings:
                    print(f"Warning: Digest check failed for object {obj}.")
            if is_valid:
                good_objects += 1
    except Exception as e:
        if show_warnings:
            print(f"Error during validation: {e}")

    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    try:
        if not os.path.exists(self.storage_root):
            os.makedirs(self.storage_root)
            with open(os.path.join(self.storage_root, 'ocfl_1.0.txt'), 'w') as f:
                f.write('1.0')
        else:
            raise FileExistsError(f"The storage root {self.storage_root} already exists.")
    except Exception as e:
        raise Exception(f"An error occurred while initializing the OCFL storage root: {e}")

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not isinstance(version_dirs, list):
        raise ValueError("version_dirs must be a list of directory names.")

    root_inventory = {}
    version_inventories = []

    for version_dir in version_dirs:
        try:
            with open(os.path.join(version_dir, 'inventory.json'), 'r') as f:
                inventory = json.load(f)
                version_inventories.append(inventory)

                if not root_inventory:
                    root_inventory = inventory
                else:
                    for item, digest in inventory.items():
                        if root_inventory.get(item) != digest:
                            print(f"Digest mismatch for {item}: expected {root_inventory.get(item)}, got {digest}")
        except FileNotFoundError:
            print(f"Inventory file not found for version {version_dir}.")
        except json.JSONDecodeError:
            print(f"Error decoding inventory JSON for version {version_dir}.")

    # Further validation logic can be added here if needed
    return version_inventories

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    try:
        if os.path.isfile(path):
            return 'file'

        if not os.path.isdir(path):
            return 'not a valid path'

        namaste_file = os.path.join(path, '0=ocfl_1.0')
        if os.path.isfile(namaste_file):
            return 'root'

        namaste_file = os.path.join(path, '0=ocfl_object_1.0')
        if os.path.isfile(namaste_file):
            return 'object'

        return 'unknown OCFL type'

    except Exception as e:
        return str(e)

