def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    import argparse

    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers(dest='subparser_name')

    # Example subparsers
    parser_a = subparsers.add_parser('a')
    parser_a.add_argument('--foo', type=int, help='foo help')

    parser_b = subparsers.add_parser('b')
    parser_b.add_argument('--bar', type=str, help='bar help')

    try:
        args = parser.parse_args(unparsed_arguments)
        if args.subparser_name is None:
            return {"global": args}
        else:
            return {args.subparser_name: args}
    except argparse.ArgumentError as e:
        print(f"Argument Error: {e}")
        return {}
    except Exception as e:
        print(f"An error occurred: {e}")
        return {}

def deep_merge_nodes(nodes):
    '''Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    merged = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged:
            if isinstance(merged[key][1], MappingNode) and isinstance(value_node, MappingNode):
                merged[key] = (key_node, deep_merge_nodes(merged[key][1].value + value_node.value))
            else:
                merged[key] = (key_node, value_node)
        else:
            merged[key] = (key_node, value_node)

    return list(merged.values())

