def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise ValueError("All elements must be dictionaries.")
        for key, value in d.items():
            if not isinstance(value, (int, float)):
                raise ValueError("All values must be numbers.")
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    try:
        if not isinstance(url, str):
            raise ValueError("URL must be a string")
        if not isinstance(url_args, dict):
            raise ValueError("url_args must be a dictionary")

        for key, value in url_args.items():
            placeholder = f'{{{key}}}'
            if placeholder in url:
                url = url.replace(placeholder, str(value))

        return url

    except Exception as e:
        raise ValueError(f"An error occurred while replacing URL arguments: {str(e)}")

