def unquote(name):
    """Remove quote from the given name."""
    if isinstance(name, str):
        return re.sub(r'^["\']|["\']$', '', name)
    return name

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        result = subprocess.run(['git', 'status', '--porcelain', ignored], capture_output=True, text=True, check=True)
        ignored_files = [line.split()[1] for line in result.stdout.splitlines() if line.startswith('!! ')]
        sorted_ignored_files = sorted(ignored_files)
        return ', '.join(sorted_ignored_files)
    except subprocess.CalledProcessError as e:
        print(f"Error executing git command: {e}")
        return ""
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return ""

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None

    try:
        parts = frequency.split()
        if len(parts) != 2:
            raise ValueError(f"Invalid frequency format: {frequency}")

        count = int(parts[0])
        unit = parts[1].strip().lower()

        if unit.endswith('s'):
            unit = unit[:-1]

        if unit == 'week':
            return datetime.timedelta(weeks=count)
        elif unit == 'day':
            return datetime.timedelta(days=count)
        elif unit == 'hour':
            return datetime.timedelta(hours=count)
        elif unit == 'minute':
            return datetime.timedelta(minutes=count)
        elif unit == 'second':
            return datetime.timedelta(seconds=count)
        else:
            raise ValueError(f"Unknown time unit: {unit}")

    except (ValueError, TypeError):
        raise ValueError(f"Unable to parse frequency: {frequency}")

def is_gitbash():
    """
