def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import os
    import configparser

    configurations = {}
    error_records = []

    if overrides is None:
        overrides = {}

    for filename in config_filenames:
        parser = configparser.ConfigParser()
        try:
            with open(filename) as f:
                parser.read_file(f)
                if resolve_env:
                    for section in parser.sections():
                        for key, value in parser.items(section):
                            parser[section][key] = os.path.expandvars(value)

                # Apply overrides
                for key, value in overrides.items():
                    if key in parser:
                        parser[key].update(value)

                configurations[filename] = {section: dict(parser.items(section)) for section in parser.sections()}

        except (configparser.Error, IOError, OSError) as e:
            record = logging.LogRecord(name='ConfigLoader', level=logging.ERROR, pathname=filename, lineno=0,
                                       msg=f'Error parsing configuration file {filename}: {str(e)}',
                                       args=(), exc_info=True)
            error_records.append(record)

    return configurations, error_records

