def _verify(iface, candidate, tentative=False, vtype=None):
    """Verify that *candidate* might correctly provide *iface*."""

    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not provide the interface {iface}")

    required_methods = set(iface.names(also_provided=True))
    provided_methods = set(dir(candidate))

    missing_methods = required_methods - provided_methods
    for method_name in missing_methods:
        errors.append(f"Method {method_name} is not implemented")

    for method_name in required_methods:
        if method_name in provided_methods:
            candidate_method = getattr(candidate, method_name)
            iface_method = iface[method_name]
            if not callable(candidate_method):
                errors.append(f"Attribute {method_name} is not callable")
                continue
            try:
                iface_method.getSignatureInfo()
                candidate_signature = inspect.signature(candidate_method)
                iface_signature = iface_method.getSignatureInfo()['signature']
                if not candidate_signature.parameters.keys() == iface_signature.parameters.keys():
                    errors.append(f"Method {method_name} has incorrect signature")
            except (TypeError, AttributeError):
                pass  # Cannot verify signature for this method

    required_attributes = set(iface.names(also_provided=True, include_methods=False))
    missing_attributes = required_attributes - provided_methods
    for attribute_name in missing_attributes:
        errors.append(f"Attribute {attribute_name} is not defined")

    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid('\n'.join(errors))

    return True

def verifyObject(iface, candidate, tentative=False):
    """Verify that *candidate* might correctly provide *iface*."""
    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"{candidate} does not provide {iface}")

    for name in iface:
        if name.startswith('__'):
            continue
        if name in iface._InterfaceClass__basesonlyattrs:
            if iface[name] is getattr(candidate, name, None):
                continue
            errors.append(f"{candidate} does not provide {name} with the correct value from {iface}")
            continue

        if name in iface._InterfaceClass__iroattrs:
            if not callable(getattr(candidate, name, None)):
                errors.append(f"{candidate} does not provide method {name}")
                continue

            if hasattr(iface[name], 'getSignatureString'):
                try:
                    iface[name].bind(candidate)
                except TypeError as e:
                    errors.append(f"{candidate} method {name} does not have the correct signature: {e}")
                continue

        if not hasattr(candidate, name):
            errors.append(f"{candidate} does not provide attribute {name}")
            continue

    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid("\n".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not iface or not candidate:
        raise ValueError("Both iface and candidate must be provided.")

    if issubclass(candidate, iface):
        return True

    if tentative:
        # Check for tentative compatibility, e.g., checking for some methods.
        required_methods = set(attr for attr in dir(iface) if callable(getattr(iface, attr)) and not attr.startswith("__"))
        candidate_methods = set(attr for attr in dir(candidate) if callable(getattr(candidate, attr)))
        if required_methods.issubset(candidate_methods):
            return True

    return False

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc:
        return explicit_mc
    metaclass = None
    for base in bases:
        if isinstance(base, type):
            if metaclass is not None:
                if metaclass is not base and not issubclass(metaclass, base) and not issubclass(base, metaclass):
                    raise TypeError("metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of the metaclasses of all its bases")
            metaclass = base.__class__
    return metaclass if metaclass else type

