        os.environ['CONFIG_PATH'] = '/path/to/default/config'

def extend_cli(self, root_subparsers):
    """
    Adds the spec cli options to to the main entry point.

    :param subparser: the subparser object to extend.
    """
    try:
        parser = root_subparsers.add_parser(self.name, help=self.description)
        self.add_arguments(parser)
    except Exception as e:
        print(f"An error occurred while extending CLI: {e}")

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError(f"Path '{path}' does not start with root '{root}'")
    stripped_path = path[len(root):]
    # Remove leading slash if present after stripping root
    if stripped_path.startswith('/'):
        stripped_path = stripped_path[1:]
    return stripped_path
